      "valueString": "On room air"
    },
    {
      "resourceType": "Observation",
      "id": "observation-5",
      "status": "final",
      "code": {
        "text": "Temperature"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Afebrile; no numeric temperature recorded"
    },
    {
      "resourceType": "Observation",
      "id": "observation-6",
      "status": "final",
      "code": {
        "text": "Body mass index"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueQuantity": {
        "value": 23,
        "unit": "kg/m2"
      },
      "valueString": "Approximate; patient estimate"
    },
    {
      "resourceType": "Observation",
      "id": "observation-7",
      "status": "final",
      "code": {
        "text": "Fatigue and exhaustion"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports approximately 4–5 months of progressive exhaustion and fatigue despite 7–8 hours in bed; describes feeling “running on empty.”"
    },
    {
      "resourceType": "Observation",
      "id": "observation-8",
      "status": "final",
      "code": {
        "text": "Sleep"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Sleep is non-restorative. Reports difficulty switching off, especially after late shifts, and often scrolls on her phone in bed. Sleeps approximately 5–6 hours before shifts and somewhat more on days off; wakes early on work days with anticipatory anxiety."
    },
    {
      "resourceType": "Observation",
      "id": "observation-9",
      "status": "final",
      "code": {
        "text": "Work-related mood and emotional symptoms"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports low mood mainly around work and at the end of a run of shifts; tearful after shifts. Reports being able to enjoy time with partner and friends on days off and denies global anhedonia."
    },
    {
      "resourceType": "Observation",
      "id": "observation-10",
      "status": "final",
      "code": {
        "text": "Irritability"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports increased irritability and being snappy with colleagues, occasionally with patients; finds this distressing."
    },
    {
      "resourceType": "Observation",
      "id": "observation-11",
      "status": "final",
      "code": {
        "text": "Sense of accomplishment and interest in work"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports reduced sense of accomplishment (“whatever I do it’s never enough”), reduced interest in nursing, and is contemplating leaving nursing."
    },
    {
      "resourceType": "Observation",
      "id": "observation-12",
      "status": "final",
      "code": {
        "text": "Concentration"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports reduced concentration at work; concentration is okay at home."
    },
    {
      "resourceType": "Observation",
      "id": "observation-13",
      "status": "final",
      "code": {
        "text": "Appetite"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Appetite is variable and reduced on work days."
    },
    {
      "resourceType": "Observation",
      "id": "observation-14",
      "status": "final",
      "code": {
        "text": "Weight change"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports mild estimated weight loss of 3–4 kg over approximately 3 months; not objectively recorded."
    },
    {
      "resourceType": "Observation",
      "id": "observation-15",
      "status": "final",
      "code": {
        "text": "Tension headache"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports intermittent tension headaches."
    },
    {
      "resourceType": "Observation",
      "id": "observation-16",
      "status": "final",
      "code": {
        "text": "Gastrointestinal symptoms"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports a “nervy stomach” and loose stools on work days."
    },
    {
      "resourceType": "Observation",
      "id": "observation-17",
      "status": "final",
      "code": {
        "text": "Anticipatory anxiety"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports worry the night before shifts, racing thoughts about patient load, and fear of making errors. Denies panic attacks."
    },
    {
      "resourceType": "Observation",
      "id": "observation-18",
      "status": "final",
      "code": {
        "text": "Psychomotor activity"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "No psychomotor retardation or agitation on examination."
    },
    {
      "resourceType": "Observation",
      "id": "observation-19",
      "status": "final",
      "code": {
        "text": "Suicidal thoughts"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Denies suicidal ideation, including passive thoughts; states, “I’m just exhausted and over it, not going to hurt myself.”"
    },
    {
      "resourceType": "Observation",
      "id": "observation-20",
      "status": "final",
      "code": {
        "text": "Self-harm and thoughts of harming others"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Denies thoughts of self-harm and thoughts of harming others."
    },
    {
      "resourceType": "Observation",
      "id": "observation-21",
      "status": "final",
      "code": {
        "text": "Alcohol use"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports 1–2 standard glasses of wine on most days off, sometimes 3–4 after a run of shifts to “switch off.” Denies morning use and blackouts."
    },
    {
      "resourceType": "Observation",
      "id": "observation-22",
      "status": "final",
      "code": {
        "text": "Caffeine use"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports 5–6 coffees per night on night shifts and 2–3 per day otherwise; is concerned caffeine may be affecting sleep."
    },
    {
      "resourceType": "Observation",
      "id": "observation-23",
      "status": "final",
      "code": {
        "text": "Other substance use"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Denies illicit substance use and non-prescribed medication use."
    },
    {
      "resourceType": "Observation",
      "id": "observation-24",
      "status": "final",
      "code": {
        "text": "General appearance"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Well groomed; appears tired and mildly tense; intermittently impatient and checking her phone for work messages."
    },
    {
      "resourceType": "Observation",
      "id": "observation-25",
      "status": "final",
      "code": {
        "text": "Mental status examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Alert and oriented to person, place, and time. Speech normal in rate and volume, somewhat pressured when discussing work. Mood described as “exhausted and over it”; affect congruent, with brief tearfulness when describing feeling she is failing patients. Thought form coherent and logical. No delusions, hallucinations, or thought disorder observed. Insight good and judgment intact."
    },
    {
      "resourceType": "Observation",
      "id": "observation-26",
      "status": "final",
      "code": {
        "text": "Neurological examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Grossly normal."
    },
    {
      "resourceType": "Observation",
      "id": "observation-27",
      "status": "final",
      "code": {
        "text": "Abdominal examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Abdomen soft and non-tender; no masses."
    },
    {
      "resourceType": "Observation",
      "id": "observation-28",
      "status": "final",
      "code": {
        "text": "Thyroid examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "No goitre or tremor."
    },
    {
      "resourceType": "Observation",
      "id": "observation-29",
      "status": "final",
      "code": {
        "text": "Other examination findings"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Rest of examination unremarkable."
    },
    {
      "resourceType": "Observation",
      "id": "observation-30",
      "status": "final",
      "code": {
        "text": "Fever and night sweats"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Denies fever and night sweats."
    },
    {
      "resourceType": "Observation",
      "id": "observation-31",
      "status": "final",
      "code": {
        "text": "Chest symptoms"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Denies chest pain, shortness of breath, and palpitations."
    },
    {
      "resourceType": "Observation",
      "id": "observation-32",
      "status": "final",
      "code": {
        "text": "Thyroid-related symptoms"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Denies heat or cold intolerance and tremor; no bowel habit change reported apart from work-related loose stools."
    },
    {
      "resourceType": "Observation",
      "id": "observation-33",
      "status": "final",
      "code": {
        "text": "Menstrual symptoms"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "No menstrual issues volunteered today."
    }
  ]
}

